findings.existing_code:
let head: String = text.chars().take(limit).collect();
match head.rfind(' ') {
    Some(space) => format!("{}…", &head[..space]),
    None => format!("{head}…"),
}

findings.suggestion:
// Leave room for the trailing ellipsis so the result stays within `limit`
// characters: `head` is at most `limit - 1` chars, plus one for `…`.
let head: String = text.chars().take(limit.saturating_sub(1)).collect();
match head.rfind(' ') {
    Some(space) => format!("{}…", &head[..space]),
    None => format!("{head}…"),
}
